SELECT CASE WHEN s.region IN ('Central', 'East') THEN 'tier_1' ELSE 'other' END AS region_group, COUNT(*) AS inventory_count, SUM(i.quantity) AS total_quantity FROM inventory i INNER JOIN products p ON p.id = i.product_id INNER JOIN stores s ON s.id = i.store_id GROUP BY CASE WHEN s.region IN ('Central', 'East') THEN 'tier_1' ELSE 'other' END ORDER BY total_quantity DESC, region_group ASC LIMIT 20
